<script setup lang="ts">
import {
  Activity, Bell, Building2, CheckCircle2, CreditCard, KeyRound, LayoutDashboard,
  LifeBuoy, LogOut, Menu, Search, ServerCog, Settings, ShieldCheck, Users, X,
} from '@lucide/vue'
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import api from '../api'
import BrandLogo from '../components/BrandLogo.vue'
import { useAuthStore } from '../stores/auth'
import { useLocaleStore } from '../stores/locale'

const auth=useAuthStore();const locale=useLocaleStore();const route=useRoute();const router=useRouter();const data=ref<any>(null);const loading=ref(true);const menu=ref(false);const search=ref('')
const sections=['overview','academies','subscriptions','users','security','support','settings']
const section=computed(()=>sections.includes(String(route.params.section))?String(route.params.section):'overview')
const nav=[
  ['overview','Command centre',LayoutDashboard],['academies','Academies',Building2],['subscriptions','Subscriptions',CreditCard],
  ['users','Users & access',Users],['security','Security & audit',ShieldCheck],['support','Support operations',LifeBuoy],['settings','Platform settings',Settings],
]
const filteredOrganizations=computed(()=>{const value=search.value.trim().toLowerCase();if(!value)return data.value?.organizations||[];return (data.value?.organizations||[]).filter((item:any)=>[item.name_en,item.name_ar,item.email,item.city].some((field:any)=>String(field||'').toLowerCase().includes(value)))})
const title=computed(()=>locale.tr(String(nav.find(item=>item[0]===section.value)?.[1]||'Command centre')))
async function load(){loading.value=true;try{data.value=(await api.get('/platform/overview')).data}finally{loading.value=false}}
async function logout(){await auth.logout();router.replace('/')}
function initials(name:string){return name.split(' ').map(part=>part[0]).join('').slice(0,2).toUpperCase()}
onMounted(load)
</script>

<template><div class="app-shell platform-shell">
  <aside :class="{open:menu}">
    <div class="sidebar-head"><BrandLogo light/><button @click="menu=false"><X/></button></div>
    <div class="platform-identity"><span><ServerCog/></span><div><small>{{locale.tr('PLATFORM CONSOLE')}}</small><b>AcademyHub SaaS</b></div><em>LIVE</em></div>
    <nav><small>{{locale.tr('PLATFORM OPERATIONS')}}</small><RouterLink v-for="([key,label,Icon]) in nav.slice(0,6)" :key="String(key)" :to="`/admin/${key}`" :class="{active:section===key}" @click="menu=false"><component :is="Icon"/>{{locale.tr(String(label))}}</RouterLink><small>{{locale.tr('CONFIGURATION')}}</small><RouterLink :to="'/admin/settings'" :class="{active:section==='settings'}" @click="menu=false"><Settings/>{{locale.tr('Platform settings')}}</RouterLink></nav>
    <div class="sidebar-foot"><span>{{initials(auth.user?.name||'PA')}}</span><div><b>{{auth.user?.name}}</b><small>{{locale.tr('Platform administrator')}}</small></div><button :title="locale.tr('Sign out')" @click="logout"><LogOut/></button></div>
  </aside>

  <main class="dashboard-main">
    <header><button class="mobile-nav" @click="menu=true"><Menu/></button><div class="global-search"><Search/><input v-model="search" :placeholder="locale.tr('Search academies, users or IDs…')"><kbd>{{locale.tr('GLOBAL')}}</kbd></div><div class="header-actions"><span class="platform-badge"><ShieldCheck/>{{locale.tr('SUPER ADMIN')}}</span><button><Bell/></button></div></header>
    <div v-if="loading" class="loading-state"><span></span>{{locale.tr('Loading platform operations…')}}</div>
    <div v-else class="dashboard-content platform-content">
      <div class="platform-page-head"><div><span>{{locale.tr('ACADEMYHUB CONTROL PLANE')}}</span><h1>{{title}}</h1><p>{{locale.tr('Global SaaS administration — separate from every academy and teaching workspace.')}}</p></div><div class="system-health"><i></i><span><small>{{locale.tr('SYSTEM STATUS')}}</small><b>{{locale.tr('All services operational')}}</b></span></div></div>

      <template v-if="section==='overview'">
        <section class="platform-stats"><article><span><Building2/></span><small>{{locale.tr('ORGANISATIONS')}}</small><b>{{data.stats.organizations}}</b><em>{{data.stats.trial_organizations}} currently trialling</em></article><article><span><Users/></span><small>{{locale.tr('PLATFORM USERS')}}</small><b>{{data.stats.users}}</b><em>Across {{data.stats.centres}} centres</em></article><article><span><CreditCard/></span><small>{{locale.tr('PAID SUBSCRIPTIONS')}}</small><b>{{data.stats.active_subscriptions}}</b><em>{{data.stats.trial_organizations}} conversion opportunities</em></article><article><span><ShieldCheck/></span><small>{{locale.tr('PLATFORM ADMINS')}}</small><b>{{data.stats.platform_admins}}</b><em>Global privileged accounts</em></article></section>
        <section class="platform-grid"><article class="platform-card tenant-card"><div class="platform-card-head"><div><span>{{locale.tr('RECENT TENANTS')}}</span><h2>{{locale.tr('Academy portfolio')}}</h2></div><RouterLink to="/admin/academies">{{locale.tr('View all')}} →</RouterLink></div><div class="admin-table"><div class="admin-table-row table-head"><span>{{locale.tr('Academy')}}</span><span>{{locale.tr('Plan status')}}</span><span>{{locale.tr('Centres')}}</span><span>{{locale.tr('People')}}</span></div><div v-for="organization in data.organizations.slice(0,5)" :key="organization.public_id" class="admin-table-row"><span class="tenant-name"><i>{{initials(organization.name_en||organization.name_ar)}}</i><b>{{locale.locale==='ar'?(organization.name_ar||organization.name_en):(organization.name_en||organization.name_ar)}}<small>{{organization.email||organization.public_id}}</small></b></span><span><em class="status-pill" :class="organization.subscription_status">{{organization.subscription_status}}</em></span><span>{{organization.branches_count}}</span><span>{{organization.users_count}}</span></div></div></article><article class="platform-card ops-card"><div class="platform-card-head"><div><span>{{locale.tr('OPERATIONAL WATCH')}}</span><h2>{{locale.tr('What needs attention')}}</h2></div><Activity/></div><ul><li><span class="watch-icon trial"><CreditCard/></span><div><b>{{data.stats.trial_organizations}} trial {{data.stats.trial_organizations===1?'academy':'academies'}}</b><p>Track conversion and expiry before access changes.</p></div></li><li><span class="watch-icon secure"><KeyRound/></span><div><b>{{data.stats.platform_admins}} privileged {{data.stats.platform_admins===1?'account':'accounts'}}</b><p>Keep global access intentionally small.</p></div></li><li><span class="watch-icon healthy"><CheckCircle2/></span><div><b>{{locale.tr('Tenant isolation healthy')}}</b><p>Organisation and centre middleware are enforced.</p></div></li></ul></article></section>
      </template>

      <template v-else-if="section==='academies'"><section class="platform-card full-card"><div class="platform-card-head"><div><span>TENANT DIRECTORY</span><h2>All academies</h2><p>Global visibility for support and subscription operations.</p></div><em>{{filteredOrganizations.length}} results</em></div><div class="admin-table academy-directory"><div class="admin-table-row table-head"><span>Academy</span><span>Location</span><span>Subscription</span><span>Centres</span><span>Users</span><span>Created</span></div><div v-for="organization in filteredOrganizations" :key="organization.public_id" class="admin-table-row"><span class="tenant-name"><i>{{initials(organization.name_en||organization.name_ar)}}</i><b>{{organization.name_en||organization.name_ar}}<small>{{organization.email||organization.public_id}}</small></b></span><span>{{organization.city||'Not set'}}</span><span><em class="status-pill" :class="organization.subscription_status">{{organization.subscription_status}}</em></span><span>{{organization.branches_count}}</span><span>{{organization.users_count}}</span><span>{{organization.created_at}}</span></div></div></section></template>

      <template v-else-if="section==='subscriptions'"><section class="platform-stats subscription-stats"><article><span><CreditCard/></span><small>ACTIVE</small><b>{{data.subscription_breakdown.active||0}}</b><em>Paying organisations</em></article><article><span><Activity/></span><small>TRIAL</small><b>{{data.subscription_breakdown.trial||0}}</b><em>In evaluation period</em></article><article><span><ShieldCheck/></span><small>TOTAL TENANTS</small><b>{{data.stats.organizations}}</b><em>All subscription states</em></article></section><section class="platform-card full-card"><div class="platform-card-head"><div><span>SUBSCRIPTION OPERATIONS</span><h2>Plans and lifecycle</h2><p>Review tenant plan status without entering their teaching workspace.</p></div></div><div class="admin-table"><div class="admin-table-row table-head"><span>Academy</span><span>Status</span><span>Trial ends</span><span>Centres</span></div><div v-for="organization in data.organizations" :key="organization.public_id" class="admin-table-row"><span class="tenant-name"><i>{{initials(organization.name_en||organization.name_ar)}}</i><b>{{organization.name_en||organization.name_ar}}<small>{{organization.public_id}}</small></b></span><span><em class="status-pill" :class="organization.subscription_status">{{organization.subscription_status}}</em></span><span>{{organization.trial_ends_at||'—'}}</span><span>{{organization.branches_count}}</span></div></div></section></template>

      <template v-else-if="section==='users'"><section class="platform-card full-card"><div class="platform-card-head"><div><span>IDENTITY DIRECTORY</span><h2>Recent platform users</h2><p>Account identity and privilege overview across all tenants.</p></div><em>{{data.stats.users}} total</em></div><div class="admin-table user-directory"><div class="admin-table-row table-head"><span>User</span><span>Identity status</span><span>Access level</span><span>Joined</span></div><div v-for="user in data.recent_users" :key="user.id" class="admin-table-row"><span class="tenant-name"><i>{{initials(user.name)}}</i><b>{{user.name}}<small>{{user.email}}</small></b></span><span><em class="status-pill" :class="user.verified?'active':'pending'">{{user.verified?'Verified':'Unverified'}}</em></span><span>{{user.is_platform_admin?'Platform administrator':'Tenant user'}}</span><span>{{user.created_at}}</span></div></div></section></template>

      <template v-else-if="section==='security'"><section class="platform-grid"><article class="platform-card security-summary"><div class="platform-card-head"><div><span>PRIVILEGED ACCESS</span><h2>Security posture</h2></div><ShieldCheck/></div><div class="security-score"><strong>A</strong><div><b>Core controls enabled</b><p>Email verification, signed recovery, CSRF rotation and tenant boundaries are active.</p></div></div><ul><li><CheckCircle2/>Verified identity required before tenant access</li><li><CheckCircle2/>Global routes restricted to platform admins</li><li><CheckCircle2/>Organisation and centre context resolved server-side</li></ul></article><article class="platform-card"><div class="platform-card-head"><div><span>RECENT AUDIT EVENTS</span><h2>Platform activity</h2></div><Activity/></div><div class="audit-list"><div v-for="event in data.recent_activity" :key="event.id"><span></span><b>{{event.event}}</b><small>{{event.created_at}}</small></div><p v-if="!data.recent_activity.length">No audit events recorded yet.</p></div></article></section></template>

      <template v-else-if="section==='support'"><section class="empty-admin-state"><span><LifeBuoy/></span><small>SUPPORT OPERATIONS</small><h2>A clean place for tenant support.</h2><p>Academy lookup is already available from the global search. Ticket queues, impersonation approvals and service notices will live here without exposing classroom tools.</p><div><b>0</b><span>Open support cases</span></div></section></template>

      <template v-else><section class="settings-grid"><article><span><ServerCog/></span><small>PLATFORM IDENTITY</small><h2>AcademyHub SaaS</h2><p>Global product name, sender identity and public URLs.</p><button disabled>Configuration coming next</button></article><article><span><KeyRound/></span><small>AUTHENTICATION</small><h2>Secure by default</h2><p>Verified email and protected password recovery are enabled.</p><em>Enabled</em></article><article><span><Bell/></span><small>OUTBOUND EMAIL</small><h2>Development mail</h2><p>Messages currently use the Laravel log transport until production SMTP is configured.</p><em class="warning">Needs SMTP</em></article></section></template>
    </div>
  </main>
</div></template>
